"""Local mail reconciliation at the TKLBAM restore boundary."""
import importlib.machinery
import importlib.util
from pathlib import Path
import re

HELPER = Path('/usr/lib/inithooks/bin/turnkey-hub')


def custom_sender_policy(helper, state):
    """Replace only the complete sender-map settings generated by this helper."""
    values = helper.cf_entries((helper.POSTFIX_DIR / 'main.cf').read_text())
    previous = dict(state.get('baseline', {}), **state.get('owned_options', {}))
    policy = {}
    for key, suffix in (('sender_canonical_maps', 'sender'), ('smtp_header_checks', 'headers')):
        generated = r'regexp:' + re.escape(str(helper.POSTFIX_DIR)) + r'/turnkey-mail-[0-9a-f]{16}\.' + suffix
        if re.fullmatch(generated, values.get(key, '')):
            policy[key] = previous.get(key)
            if key == 'sender_canonical_maps':
                policy['sender_canonical_classes'] = previous.get('sender_canonical_classes')
    return policy


def restore_mail():
    loader = importlib.machinery.SourceFileLoader('turnkey_hub_restore', str(HELPER))
    spec = importlib.util.spec_from_loader(loader.name, loader)
    helper = importlib.util.module_from_spec(spec)
    loader.exec_module(helper)
    with helper.locked():
        client = helper.Mail()
        active = client.state.get('active')
        if not active:
            return
        if active.get("mode") not in ("hub", "custom"):
            raise helper.Error("Saved destination mail settings are invalid.")
        config = helper.checked_config(dict(active, version=1), active.get('password'),
                                       custom=active.get('mode') == 'custom')
        # The preserved local configuration was authenticated before the restore.
        # Repair its owned options/maps without depending on remote availability.
        policy = custom_sender_policy(helper, client.state) if config['mode'] == 'custom' else None
        client.apply(config, verify=False, restore_sender_policy=policy)
